using System;
using System.IO;
using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEditor.SceneManagement;
namespace IanGame.Editor {
// Local, project-scoped fallback when the session exposes no Unity MCP tools.
// Only explicit editor commands are accepted; no arbitrary code execution or save deletion.
[InitializeOnLoad]public static class Phase26EditorBridge {
 [MenuItem("Ian/Developer QA Center/End Automated Save Protection")]static void ReleaseSaveProtection(){if(Application.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop automated Play first");SessionState.SetBool("ian.phase26.protectWrites",false);SessionState.SetBool("ian.phase26.automationHold",false);}
 [Serializable]class Request {public string id,command;}
 [Serializable]class Reply {public string id,status,scene,message;public bool playing,compiling;public string utc;}
 const string DirectoryPath="Docs/Phase26",RequestPath=DirectoryPath+"/EditorCommand.json";
 static double next,reloadAt;static bool enteredPlay;static string last;
 static Phase26EditorBridge(){reloadAt=EditorApplication.timeSinceStartup;enteredPlay=EditorApplication.isPlaying;Directory.CreateDirectory(DirectoryPath);last=SessionState.GetString("ian.phase26.lastCommand","");EditorApplication.playModeStateChanged+=state=>{if(state==PlayModeStateChange.EnteredPlayMode)enteredPlay=true;if(state==PlayModeStateChange.ExitingEditMode||state==PlayModeStateChange.ExitingPlayMode||state==PlayModeStateChange.EnteredEditMode)enteredPlay=false;if(state==PlayModeStateChange.ExitingEditMode)SessionState.SetBool("ian.phase26.protectWrites",!string.IsNullOrEmpty(SessionState.GetString("ian.phase26.pendingTest",""))||!string.IsNullOrEmpty(SessionState.GetString("ian.phase26.queuedTest","")));};EditorApplication.update+=Tick;Write("ready","Editor bridge loaded");}
 static void Write(string status,string message,string id=""){File.WriteAllText(DirectoryPath+"/EDITOR_STATE.json",JsonUtility.ToJson(new Reply{id=id,status=status,message=message,scene=UnityEngine.SceneManagement.SceneManager.GetActiveScene().name,playing=Application.isPlaying,compiling=EditorApplication.isCompiling,utc=DateTime.UtcNow.ToString("O")},true));}
 static void Tick(){if(EditorApplication.timeSinceStartup<next||EditorApplication.isCompiling||EditorApplication.isUpdating)return;next=EditorApplication.timeSinceStartup+.25;
  string queued=SessionState.GetString("ian.phase26.queuedTest","");if(queued!=""&&!Application.isPlaying&&!EditorApplication.isPlayingOrWillChangePlaymode&&EditorApplication.timeSinceStartup-reloadAt>=2){SessionState.SetString("ian.phase26.queuedTest","");EditorSceneManager.OpenScene("Assets/_Game/Scenes/Bootstrap.unity");SessionState.SetString("ian.phase26.pendingTest",queued);enteredPlay=false;Application.runInBackground=true;EditorApplication.isPlaying=true;Write("starting",queued,SessionState.GetString("ian.phase26.queuedId",""));return;}
  string pending=SessionState.GetString("ian.phase26.pendingTest","");if(pending!=""&&pending!="qaFramework"&&enteredPlay&&Application.isPlaying&&GameContext.Instance!=null&&GameContext.Instance.game.State!=GameState.Starting&&GameContext.Instance.game.phase23.Jobs!=null&&!GameContext.Instance.transitions.IsTransitioning&&GameContext.Instance.transitions.CurrentScene==SceneId.MainMenu){SessionState.SetString("ian.phase26.pendingTest","");try{var type=AppDomain.CurrentDomain.GetAssemblies().Select(a=>a.GetType("IanGame.Editor.Phase26Verification")).FirstOrDefault(t=>t!=null);if(type==null)throw new Exception("Phase26Verification not compiled");var go=new GameObject("Phase26 isolated verification");go.AddComponent(type).SendMessage("Begin",pending);Write("testing",pending);}catch(Exception e){Write("error",e.ToString());}}
  if(!File.Exists(RequestPath))return;Request r;try{r=JsonUtility.FromJson<Request>(File.ReadAllText(RequestPath));}catch{return;}if(r==null||string.IsNullOrEmpty(r.id)||r.id==last)return;last=r.id;SessionState.SetString("ian.phase26.lastCommand",last);File.Delete(RequestPath);
  if(r.command!="info"&&r.command!="releaseSaveGuard")SessionState.SetBool("ian.phase26.automationHold",true);
  try{switch(r.command){case "releaseSaveGuard":if(Application.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode||SessionState.GetString("ian.phase26.pendingTest","")!=""||SessionState.GetString("ian.phase26.queuedTest","")!="")throw new Exception("Finish automated Play verification first");SessionState.SetBool("ian.phase26.protectWrites",false);SessionState.SetBool("ian.phase26.automationHold",false);Write("released","Normal production save access restored for subsequent manual Play",r.id);break;case "pre28SaveGuardEdit":if(Application.isPlaying)throw new Exception("Stop Play first");var guardProbe=new GameObject("QA edit save boundary probe");try{var saveProbe=guardProbe.AddComponent<SaveManager>();bool wrote=saveProbe.SaveAutomatic(null,null,false,"qa-edit-probe",1,out var guardMessage);if(wrote||!guardMessage.Contains("자동 검증"))throw new Exception("Edit guard not retained: "+guardMessage);Write("guarded",guardMessage,r.id);}finally{UnityEngine.Object.DestroyImmediate(guardProbe);}break;case "sceneAudit":SceneArchitectureBuilder.Audit();Write("audited","Source scene hierarchy",r.id);break;case "familyBuild":if(Application.isPlaying)throw new Exception("Stop Play first");WorldQualityRecoverySetup.BuildFamilyLife();Write("saved","Family home, parent schedules and existing action adapters saved",r.id);break;case "facilityBuild":if(Application.isPlaying)throw new Exception("Stop Play first");WorldQualityRecoverySetup.StandardizeFacilities();Write("saved","Existing facilities standardized; company/home protected",r.id);break;case "doorAudit":DoorVisualAudit.Run();Write("audited","door alignment",r.id);break;case "doorVisualFinish":if(Application.isPlaying)throw new Exception("Stop Play first");var savedScene=EditorSceneManager.OpenScene("Assets/_Game/Scenes/LifeWorld.unity");if(savedScene.isDirty)EditorSceneManager.SaveScene(savedScene);AssetDatabase.SaveAssets();Write("saved","LifeWorld dirty="+savedScene.isDirty+" target="+EditorUserBuildSettings.activeBuildTarget+" isolatedWriteGuard="+SessionState.GetBool("ian.phase26.protectWrites",false)+" automationHold="+SessionState.GetBool("ian.phase26.automationHold",false),r.id);break;case "info":Write("ready","Unity "+Application.unityVersion,r.id);break;case "build":LifeWorldBuilder.Build();Write("built","LifeWorld scene, catalog, GameContext and UI saved",r.id);break;case "familyInteraction":case "familyArchitecture":case "familyHousehold":case "familyCheck":case "familyActions":case "familyDoors":case "facilityCompanyShift":case "facilityClerkExit":case "facilityTerminals":case "facilityActorsRemaining":case "facilityCaptureAfter":case "facilityActors":case "facilityFunctions":case "facilityRegistry":case "facilityMobile":case "facilityCheck":case "facilityCaptureBefore":case "pre28SaveGuard":case "pre28DoorRetest":case "pre28World":case "pre28Walking":case "pre28Growth":case "pre28UI":case "pre28FinanceGate":case "pre28Full":case "pre28Failed":case "pre28LifeResume":case "pre28Life":case "pre28Birth":case "doorEntryCapture":case "doorVisual":case "criticalVisitors":case "criticalCapture":case "criticalDoorCycles":case "criticalFacilities":case "criticalGrowth":case "criticalDoors":case "advancedRecoverySafety":case "advancedRecoveryPolish":case "advancedRecovery":case "advancedQAFailed":case "advancedQA":case "advancedProperty":case "advancedResidentVisual":case "advancedResidents":case "advancedMobile":case "advancedDoors":case "advancedAnimation":case "masterCapture":case "master":case "visual":case "home":case "quality":case "input":case "stageA":case "cycle":case "ui":case "edge":case "integration":case "capture":if(Application.isPlaying||EditorApplication.isPlayingOrWillChangePlaymode)throw new Exception("Stop the previous Play session first");SessionState.SetBool("ian.phase26.protectWrites",true);AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);SessionState.SetString("ian.phase26.queuedTest",r.command);SessionState.SetString("ian.phase26.queuedId",r.id);reloadAt=EditorApplication.timeSinceStartup;Write("queued","Waiting for stable script import",r.id);break;case "stop":SessionState.SetString("ian.phase26.queuedTest","");SessionState.SetString("ian.phase26.pendingTest","");EditorApplication.isPlaying=false;Write("stopping","Play stopped",r.id);break;case "refresh":AssetDatabase.Refresh(ImportAssetOptions.ForceSynchronousImport);UnityEditor.Compilation.CompilationPipeline.RequestScriptCompilation();Write("refresh","Compilation requested",r.id);break;default:throw new Exception("Unknown editor command "+r.command);}}catch(Exception e){Write("error",e.ToString(),r.id);}
 }
}
}
